export const VOICE_FILES={"אני: הלו? נועה? מה קרה כל כך מוקדם?": ["./assets/voices/voice175-271d999ac3b9ea.mp3"], "נועה: בוקר טוב, אדם. היום אנחנו בודקים את הקורים של העכביש בתא שמונה. אנחנו מנסים לפתח חבלים חזקים שיעזרו לחלץ אנשים. אני צריכה אותך איתנו במעבדה.": ["./assets/voices/voice175-18afc12ce394bb.mp3"], "נועה: תלבש את בגדי העבודה, קח את התיק ואת תג העובד, וסע אלינו. הצוות כבר מתכונן. ואל תיגש לתא לפני שנבדוק שהזכוכית נעולה. נתראה בקרוב.": ["./assets/voices/voice175-c09bebda97c4ac.mp3"], "בוקר טוב! זה הבית שלך. אתה עובד כעוזר מחקר במעבדת העכבישים. היום הצוות יבדוק קורים חזקים לחילוץ אנשים. גש לארון הבגדים מימין והתארגן לעבודה.": ["./assets/voices/voice175-4e0f0b51953579.mp3"], "לבשת את בגדי העבודה. עכשיו צריך לקחת את התיק ותג העובד.": ["./assets/voices/voice175-80565b99fb3502.mp3"], "בתיק יש פנס ותג עובד. המעבדה נמצאת באחוזה ישנה מחוץ לעיר. קיבלת הודעה: ״נפגשים ליד תא 08״. כשאתה מוכן, גש לדלת שבין החלונות ולחץ E.": ["./assets/voices/voice175-28a727c98274e5.mp3"], "בדרך לאחוזת המחקר…": ["./assets/voices/voice175-6f351dd7d73973.mp3"], "התארגן לעבודה. בגדי העבודה נמצאים בארון, והתיק ותג העובד על השולחן.": ["./assets/voices/voice175-8ecd77c2041528.mp3"], "רובוט: בוקר טוב! ברוך הבא לאחוזת המחקר. ד״ר נועה מחכה לך משמאל.": ["./assets/voices/voice175-4b1c873229a05d.mp3"], "נועה: אנחנו מנסים ליצור קורי משי לחילוץ אנשים. אמיר יסביר לך איך מודדים את החוזק.": ["./assets/voices/voice175-d0e3e7a448408f.mp3"], "אמיר: החוט הזה יכול לשאת משקל עצום. אבל העכביש גדל מאז אתמול. מאיה ביקשה לבדוק אותו שוב.": ["./assets/voices/voice175-8f5e2c746c9341.mp3"], "מאיה: בדיקה קצרה בלבד. אם הגודל משתנה, עוצרים מיד. יואב הכין את המחשב שמימין.": ["./assets/voices/voice175-09f0a7449c6ab1.mp3"], "יואב: החיישנים מוכנים. עבור לכפתור שליד התא והתחל בדיקת משי.": ["./assets/voices/voice175-c33cce7c054ed3.mp3"], "מאיה: רגע… המדידה עולה מהר מדי. תעצרו את ההזנה!": ["./assets/voices/voice175-65d8046a2656fa.mp3"], "המכונית בחניה. גש לדלת הנהג ולחץ E כדי להיכנס.": ["./assets/voices/voice175-18876596105993.mp3"], "כריזה: מצב חירום במעבדה. כל אנשי הצוות, להתפנות מיד דרך יציאת החירום!": ["./assets/voices/voice175-4edd27ac778a41.mp3"], "יואב: הדלת נסגרת! רגע, הוא עדיין בפנים!": ["./assets/voices/voice175-1f672019822b04.mp3"], "מערכת זיכרון פעילה. תודה שחיברת את הסוללה. אני יחידת תחזוקה 08. בניתי את המסילות, תיקנתי את הדלתות, וזכרתי את מה שהחוקרים העדיפו לשכוח.": ["./assets/voices/voice175-e9cff392acdb38.mp3"], "רצינו לעזור לאנשים. קורי עכביש הם קלים וחזקים. החוקרים חלמו על חבלי חילוץ דקים שיצליחו לשאת משקל גדול מתוך בניינים שקרסו.": ["./assets/voices/voice175-71abbaf1671227.mp3"], "בתחילת ניסוי 08 היה כאן עכביש קטן. מדדנו כמה משי הוא טווה ובדקנו כל חוט. במשך שבועות הכול נראה רגיל. ואז הביאו דגימה מתחנת המחקר שמתחת לבית.": ["./assets/voices/voice175-1926fc24fcc36a.mp3"], "הדגימה שינתה את המשי. החוטים נעשו עבים יותר, אבל העכביש התחיל לגדול. ביקשתי להפסיק. המחשב הישן לא אישר את פקודת הכיבוי, וההזנה נמשכה כל הלילה.": ["./assets/voices/voice175-3d230f36e96be9.mp3"], "הוא למד את התנועות שלנו. בזמן שהחוקרים הביטו לרצפה, הוא טיפס לתקרה. על הזכוכית הופיע סדק ראשון. אחר כך שמענו שלוש נקישות מבפנים.": ["./assets/voices/voice175-60a8879fbbd701.mp3"], "הזכוכית נפרצה. כיביתי את הדלתות כדי לעצור אותו, אבל הוא עבר דרך פתח התחזוקה מעליהן. זו הסיבה שאני אומר לך לבדוק גם את התקרה.": ["./assets/voices/voice175-5427f6c05f7b67.mp3"], "השוטרים וצוות החילוץ הגיעו בבוקר. הם עקבו אחרי קורים עד למרתף. המצלמה האחרונה הראתה מסדרון ריק, אבל המיקרופון המשיך להקליט שמונה רגליים מתקרבות.": ["./assets/voices/voice175-e1e7f651b8dcae.mp3"], "הצלחתי להוביל כמה מהחוקרים ליציאה. אחרים נשארו בתחנה התחתונה. מאז אף אחד לא ענה לקריאות שלי. את התיעוד שמרתי במחשב ליד היומן הסודי.": ["./assets/voices/voice175-0c11ae7ba17b91.mp3"], "פיצלנו את קוד המעלית לשלושה פתקים: בחדר השינה, בחדר האוכל ובחדר המשחקים. אסוף אותם לתיק וקרא את שלוש השורות לפי הסדר.": ["./assets/voices/voice175-5672fd1c7b05ba.mp3"], "במעלית יש קומות 1 ו־2, וכפתור עם סימן שאלה. בשבילו צריך כרטיס גישה. השארנו אותו במעבדה בקומה השנייה. מתחת לבית תמצא את מקור הניסוי. אל תתקרב לבור בלי להסתכל.": ["./assets/voices/voice175-8a9511232e543d.mp3"], "אם אתה רוצה לצאת, הפנס כבר אצלך. חפש גרזן. שבור את הקרשים בדלת הכניסה. העכביש לא יודע תמיד איפה אתה: פנה מעבר לפינה, התרחק בשקט, והתחבא לפני שיראה אותך.": ["./assets/voices/voice175-daba56b66ec217.mp3"], "הסוללה שלי שוב נחלשת. אשב כאן ואשמור על הארכיון. הכפתור האדום יפתח את הדלת. אם תשמע שלוש נקישות... אל תענה.": ["./assets/voices/voice175-bf55252d0a2126.mp3"], "ברח! אני אעכב אותו!": ["./assets/voices/voice175-3129bb012101ed.mp3"], "איפה אני? איפה כולם?": ["./assets/voices/voice175-77c72cb194b01b.mp3"], "מגיש החדשות: הבוקר באחוזת המחקר: מדענים יערכו היום את ניסוי 08 בקורי עכביש.": ["./assets/voices/voice175-c81d41843cc749.mp3"], "מגיש החדשות: הצוות מפתח חבלי חילוץ חזקים וקלים, שיעזרו להציל אנשים ממקומות מסוכנים.": ["./assets/voices/voice175-c9e0349603389c.mp3"], "מגיש החדשות: החוקרים מסרו שכל הבדיקות יבוצעו בתוך תא זכוכית סגור. נעדכן בהמשך היום.": ["./assets/voices/voice175-7fa15da6651d4b.mp3"], "אני: אני רוצה לראות מה אומרים בחדשות.": ["./assets/voices/voice175-5dcb942163ccf0.mp3"], "אני: לא... לאן אתה לוקח אותי?": ["./assets/voices/voice175-5df2904ebe1508.mp3"], "אני: זה הבית... אני לא מצליח להישאר ער...": ["./assets/voices/voice175-2f181bb608935a.mp3"], "אני: אני מצלם…": ["./assets/voices/voice175-c660b652dbe48a.mp3"], "אני: הוא תפס את הרגליים שלו!": ["./assets/voices/voice175-d2ea4463fb06a5.mp3"], "רובוט: רוץ למכונית! אני אעצור אותו!": ["./assets/voices/voice175-060b6c7a0fb832.mp3"], "אני: מה יקרה לרובוט? אני צריך לישון.": ["./assets/voices/voice175-e6d86af899356c.mp3"], "חדשות: התקבל תיעוד יוצא דופן מאחוזת המחקר.": ["./assets/voices/voice175-2526a5e9afce25.mp3"], "חדשות: הרובוט עיכב את העכביש ואפשר לחוקר להימלט.": ["./assets/voices/voice175-0cf9deeacae366.mp3"], "חדשות: גורלו של הרובוט עדיין לא ידוע…": ["./assets/voices/voice175-ecf4ca7ab8a358.mp3"]};
